        }
      }
      .hardware-item {
        padding: 0 60px;
        line-height: 40px;
        overflow: hidden;

        .select-holder {
          width: 50%;
          float: left;
          overflow: hidden;

          & > label {
            display: inline-block;
            width: 120px;
          }

          .el-select {
            width: calc(100% - 150px);
          }

          .tip {
            display: inline-block;
