          }

          .connect {
            background: #76ee00;
          }
        }
        .input-holder {
          width: 50%;
          float: left;
          overflow: hidden;

          & > label {
            display: inline-block;
            width: 120px;
          }

          .el-input {
            float: left;
            width: calc(100% - 124px);
          }

          .fileList {
            line-height: 20px;
            margin-left: 100px;
          }

          .el-input::after {
            top: 10px;
          }
        }
        .operation-holder {
          float: right;

          .resetButton {
            background-color: red;
          }
        }
        .autoTime {
          width: 100px;
        }
      }
    }
  }

  .loading {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .input-sn:after {
    top: 8px;
  }

  .input {
    width: 290px;
  }

  .errorTip {
    color: #e26829;
  }
  .btn-green {
    background-color: #98b42c;

    &:hover {
      background-color: #98d22c;
    }

    &:active {
      background-color: #e26829;
    }
  }
  .loading {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
  }
}
</style>



