                    if (that.headData.length <= 0) {
                      return false;
                    }
                    if (res.length <= 0) {
                      var tabItem = {};
                      var headData = that.headData;
                      for (var item of headData) {
                        if (item.label) {
                          tabItem[item.label] = "-";
                          that.tableData.push(tabItem);
                        }
                      }
                      that.tableData.length = 1;
                    } else {
                      var tableList = res.sort((a, b) => {
                        return a.head_id - b.head_id;
                      });
